internal fun DrawScope.drawWhaleColorBlocks(palette: WhaleLinePalette) {
    drawPath(StaticWhaleContours.silhouette, palette.paper)
    WhaleColorRegions.hair.forEach { drawPath(it, palette.hair) }
    WhaleColorRegions.fin.forEach { drawPath(it, palette.fin) }
    WhaleColorRegions.accent.forEach { drawPath(it, palette.accent) }
    WhaleColorRegions.frill.forEach { drawPath(it, palette.frill) }
    WhaleColorRegions.paper.forEach { drawPath(it, palette.paper) }
}
